  label?: string; 
  value: string; 
  options: string[];
  customOptions?: string[];
  onEditOption?: (opt: string) => void;
  onDeleteOption?: (opt: string) => void;
  onChange: (val: string) => void; 
  className?: string;
}> = ({ label, value, options, customOptions, onEditOption, onDeleteOption, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useOnClickOutside(ref, () => setIsOpen(false));

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-white/20 transition-colors rounded-lg flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none h-[49px]">
        {label && <p className="text-[12px] font-medium text-[rgba(255,255,255,0.35)]">{label}</p>}
        <div className="flex items-center justify-between">
          <span className="text-[13px] font-medium text-white truncate"> {value}</span>
          <Icon name="expand_more" size={18} className={`text-[rgba(218,220,224,0.75)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#000000] border border-[#595959] rounded-lg overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-top">
          <div className="max-h-60 overflow-y-auto refined-scrollbar">
            {options.includes('Add your own style') && (
              <>
                <button 
                  type="button"
                  className="w-full text-left px-2.5 py-2 text-[13px] font-medium hover:bg-[#1a1a1a] transition-colors text-[rgba(218,220,224,0.9)] flex items-center gap-2"
                  onClick={() => { onChange('Add your own style'); setIsOpen(false); }}
                >
                  <Icon name="add" size={16} className="text-[rgba(218,220,224,0.75)]" />
                  Add your own style
                </button>
                <div className="border-b border-[rgba(218,220,224,0.15)] my-1"></div>
              </>
            )}
            {options.filter(opt => opt !== 'Add your own style').map((opt) => (
              <div key={opt} className="group relative flex items-center justify-between">
                <button type="button"
                  className={`w-full text-left px-2.5 py-2 pr-12 text-[13px] font-medium hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                  onClick={() => { onChange(opt); setIsOpen(false); }}>
                  {opt}
                </button>
                {customOptions?.includes(opt) && (
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity z-10">
                    <button 
                      onClick={(e) => { e.stopPropagation(); onEditOption?.(opt); setIsOpen(false); }}
                      className="p-1 text-zinc-400 hover:text-white transition-colors"
                      title="Edit Style"
                    >
                      <Icon name="edit" size={14} />
                    </button>
                    <button 
                      onClick={(e) => { e.stopPropagation(); onDeleteOption?.(opt); setIsOpen(false); }}
                      className="p-1 text-zinc-400 hover:text-red-400 transition-colors"
                      title="Delete Style"
                    >
                      <Icon name="delete" size={14} />
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { EditorContent, Editor as TiptapEditor } from '@tiptap/react';
import { SCENE_ID_REGEX } from '../types';
import { turndownService } from '../services/turndown';

interface EditorProps {
  editor: TiptapEditor | null;
  content: string;
  onChange: (markdown: string) => void;
}

const Editor: React.FC<EditorProps> = ({ editor, content }) => {
  const lastSetMarkdownRef = useRef('');

  useEffect(() => {
    if (!editor || editor.isDestroyed || content === undefined) return;

    // Safety: check if the editor view is actually available yet.
    // Tiptap's proxy will throw if we access view or view-related properties too early.
    try {
      if (!editor.view || !editor.view.dom) return;
    } catch (e) {
      return;
    }

    const normalizedIncoming = content.trim();
    let currentMarkdown = '';
    try {
      currentMarkdown = turndownService.turndown(editor.getHTML()).trim();
    } catch (e) {
      return;
    }

    // Safety check: if content hasn't actually changed, don't force a re-render/set
    if (normalizedIncoming === currentMarkdown && lastSetMarkdownRef.current !== '') {
      return;
    }

    let isFocused = false;
    try {
      isFocused = editor.isFocused;
    } catch (e) {
      // Ignore focus check if view is not ready
    }

    if (isFocused) {
      // Normalize whitespace for a loose comparison to avoid interrupting active typing
      const cleanForCompare = (str: string) => 
        str.replace(/<!--\s*scene-id:.*?-->/g, '')
           .replace(/\s+/g, ' ')
           .trim();

      if (cleanForCompare(normalizedIncoming) === cleanForCompare(currentMarkdown)) {
        return;
      }
    }

    // Split incoming markdown by line to process blocks more robustly than double-newline splitting
    const lines = content.split('\x0a');
    let htmlBlocks: string[] = [];
    let currentParagraphLines: string[] = [];
    let lastSceneId: string | null = null;

    const processParagraph = (linesArr: string[]) => {
      if (linesArr.length === 0) return '';

      // Split lines into separate blocks when a character name or parenthetical is encountered,
      // so each gets its own <p> and CSS :has() selectors can match correctly.
      const blocks: string[] = [];
      let currentLines: string[] = [];

      const flushCurrent = () => {
        if (currentLines.length === 0) return;
        let html = '';
        for (let i = 0; i < currentLines.length; i++) {
          html += (html ? '<br>' : '') + currentLines[i];
        }
        blocks.push(`<p>${html}</p>`);
        currentLines = [];
      };

      for (let i = 0; i < linesArr.length; i++) {
        const line = linesArr[i];
        const trimmed = line.trim();
        if (!trimmed) continue;

        // Character names (Exact matches for **NAME**) — own paragraph
        if (trimmed.startsWith('**') && trimmed.endsWith('**') && !trimmed.slice(2, -2).includes('**')) {
          flushCurrent();
          blocks.push(`<p><strong>${trimmed.slice(2, -2)}</strong></p>`);
          continue;
        }

        // Character name with inline parenthetical (e.g. **NAME**_(action)_)
        const inlineParenMatch = trimmed.match(/^\*\*(.+?)\*\*\s*[_*]\(?(.*?)\)?[_*]$/);
        if (inlineParenMatch) {
          flushCurrent();
          blocks.push(`<p><strong>${inlineParenMatch[1]}</strong><em>(${inlineParenMatch[2].replace(/^\(|\)$/g, '')})</em></p>`);
          continue;
        }

        // Parentheticals (Exact matches for _(text)_ or *(text)*) — own paragraph
        const parentheticalMatch = trimmed.match(/^[_*]\s*\((.*?)\)\s*[_*]$/);
        if (parentheticalMatch) {
          flushCurrent();
          blocks.push(`<p><em>(${parentheticalMatch[1]})</em></p>`);
          continue;
        }

        // Inline formatting (Bold/Italic)
        let parsedLine = line;
        parsedLine = parsedLine.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
        parsedLine = parsedLine.replace(/__(.+?)__/g, '<strong>$1</strong>');
        parsedLine = parsedLine.replace(/\*([^*]+)\*/g, '<em>$1</em>');
        parsedLine = parsedLine.replace(/_([^_]+)_/g, '<em>$1</em>');

        currentLines.push(parsedLine);
      }
      flushCurrent();

      return blocks.join('');
    };

    const flushParagraph = () => {
      if (currentParagraphLines.length > 0) {
        htmlBlocks.push(processParagraph(currentParagraphLines));
        currentParagraphLines = [];
      }
    };

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const trimmed = line.trim();

      // Skip ID comments but store for the next heading
      const idMatch = line.match(SCENE_ID_REGEX);
      if (idMatch) {
        lastSceneId = idMatch[1];
        continue;
      }

      if (!trimmed) {
        flushParagraph();
        continue;
      }

      // Title (H1)
      if (line.startsWith('# ')) {
        flushParagraph();
        htmlBlocks.push(`<h1>${line.replace('# ', '').trim()}</h1>`);
        continue;
      }

      // Scene Heading (H3)
      if (line.startsWith('### ')) {
        flushParagraph();
        const heading = line.replace('### ', '').trim();
        const idAttr = lastSceneId ? `data-scene-id="${lastSceneId}" id="${lastSceneId}"` : '';
        lastSceneId = null; 
        htmlBlocks.push(`<h3 ${idAttr}>${heading}</h3>`);
        continue;
      }

      // Transitions (H5)
      if (line.startsWith('##### ')) {
        flushParagraph();
        htmlBlocks.push(`<h5>${line.replace('##### ', '').trim()}</h5>`);
        continue;
      }

      // Blockquotes
      if (line.startsWith('>')) {
        flushParagraph();
        const text = line.replace(/^>\s*/, '').trim();
        htmlBlocks.push(`<blockquote><p>${text}</p></blockquote>`);
        continue;
      }

      // If we got here, it's part of a paragraph
      currentParagraphLines.push(line);
    }
    flushParagraph();

    const incomingHtml = htmlBlocks.filter(b => b !== '').join('');

    // Preserve selection if the user is currently editing
    let from = 0, to = 0;
    if (isFocused) {
      const selection = editor.state.selection;
      from = selection.from;
      to = selection.to;
    }

    try {
      editor.commands.setContent(incomingHtml, { emitUpdate: false });
      lastSetMarkdownRef.current = normalizedIncoming;

      if (isFocused) {
        try {
          editor.commands.setTextSelection({ from, to });
        } catch (e) {
          // Fallback for out-of-bounds selection errors
        }
      }
    } catch (e) {
      // Failed to set content, likely because the view is not ready or was destroyed
    }
  }, [editor, content]);

  return <EditorContent editor={editor} />;
};

export default Editor;

import React from 'react';

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends React.Component<
  { children: React.ReactNode },
  ErrorBoundaryState
> {
  constructor(props: { children: React.ReactNode }) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error('ErrorBoundary caught:', error, info.componentStack);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{
          padding: '2rem',
          fontFamily: 'monospace',
          color: '#ff6b6b',
          backgroundColor: '#1a1a1a',
          minHeight: '100vh',
          overflow: 'auto'
        }}>
          <h2 style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>
            ⚠️ App crashed during render
          </h2>
          <pre style={{
            whiteSpace: 'pre-wrap',
            wordBreak: 'break-word',
            backgroundColor: '#0d0d0d',
            padding: '1rem',
            borderRadius: '8px',
            border: '1px solid #333'
          }}>
            {this.state.error?.message}
            {'\x0a\x0a'}
            {this.state.error?.stack}
          </pre>
        </div>
      );
    }
    return this.props.children;
  }
}

import React from 'react';
import { StoryboardFrame } from '../types';
import { Icon } from './Icon';
import { Tooltip } from './Tooltip';

interface FrameCardProps {
  frame: StoryboardFrame;
  aspectRatio: '16:9' | '9:16';
  isActive: boolean;
  onClick: () => void;
  onDelete: (id: string) => void;
  onGenerate: (id: string) => Promise<void>;
  isGenerating: boolean;
  isAutofilling?: boolean;
  onExpand?: () => void;
  generationFailed?: boolean;
  onStop?: () => void;
  onDismissFailure?: () => void;
}

export const FrameCard: React.FC<FrameCardProps> = ({
  frame,
  aspectRatio,
  isActive,
  onClick,
  onDelete,
  onGenerate,
  isGenerating,
  isAutofilling,
  onExpand,
  generationFailed,
  onStop,
  onDismissFailure
}) => {
  const aspectClass = aspectRatio === '16:9' ? 'aspect-video' : 'aspect-[9/16]';

  return (
    <div 
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      className="group relative flex flex-col gap-1.5 cursor-pointer"
    >
      {/* Image Container */}
      <div className={`relative ${aspectClass} rounded-[4px] overflow-hidden border border-[#DADCE0]/[0.24] transition-all duration-200 ${
        isActive ? 'outline outline-2 outline-white shadow-[inset_0_0_0_2px_rgba(0,0,0,1)]' : 'group-hover:border-white/20'
      }`}>
        {frame.imageUrl ? (
          <img 
            src={frame.imageUrl} 
            alt={frame.title} 
            className="w-full h-full object-cover" 
          />
        ) : (
          <div className="w-full h-full bg-[#DADCE0]/[0.04] flex flex-col items-center justify-center">
            <Icon name="image" size={40} className="opacity-[0.16]" />
          </div>
        )}

        {/* Loading Overlay */}
        {(isGenerating || isAutofilling) && (
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm z-20 flex flex-col items-center justify-center gap-2.5">
            <div className="flex gap-1.5 items-center">
              <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce [animation-delay:-0.3s]" />
              <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce [animation-delay:-0.15s]" />
              <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce" />
            </div>
            {isGenerating && onStop && (
              <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                <button
                  onClick={(e) => { e.stopPropagation(); onStop(); }}
                  className="px-3 py-1 rounded-full border border-[#DADCE0]/[0.24] text-[11px] font-bold text-white/80 hover:bg-white/10 transition-all font-sans"
                >
                  Stop
                </button>
              </div>
            )}
          </div>
        )}

        {/* Failed Overlay */}
        {generationFailed && !isGenerating && !isAutofilling && (
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm z-20 flex flex-col items-center justify-center gap-2">
            {/* Dismiss button */}
            {onDismissFailure && (
              <button
                onClick={(e) => { e.stopPropagation(); onDismissFailure(); }}
                className="absolute top-2 right-2 w-7 h-7 rounded-[12px] bg-black/40 flex items-center justify-center text-white/60 hover:text-white hover:bg-white/10 transition-all"
              >
                <Icon name="close" size={16} />
              </button>
            )}
            <Icon name="error" size={24} className="opacity-[0.48]" />
            <span className="text-[11px] text-white/60 font-sans">Generation failed</span>
            <button
              onClick={(e) => { e.stopPropagation(); onGenerate(frame.id); }}
              className="mt-1 px-3 py-1 rounded-full border border-[#DADCE0]/[0.24] text-[11px] font-bold text-white/80 hover:bg-white/10 transition-all font-sans"
            >
              Retry
            </button>
          </div>
        )}

        {/* Hover Actions */}
        {!isGenerating && !isAutofilling && (
          <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-all duration-200 flex gap-2">
            {frame.imageUrl && onExpand && (
              <Tooltip text="View full size">
                <button 
                  onClick={(e) => { e.stopPropagation(); onExpand(); }}
                  className="group/btn w-8 h-8 bg-black/60 backdrop-blur-md text-white rounded-[12px] transition-all flex items-center justify-center shadow-lg"
                >
                  <Icon name="open_in_full" size={18} className="opacity-[0.48] group-hover/btn:opacity-100 transition-opacity" />
                </button>
              </Tooltip>
            )}
            <Tooltip text={!frame.visualDescription?.trim() ? 'Add a description first' : frame.imageUrl ? 'Regenerate image' : 'Create image'}>
              <button 
                onClick={(e) => {
                  e.stopPropagation();
                  if (frame.visualDescription?.trim()) onGenerate(frame.id);
                }}
                disabled={!frame.visualDescription?.trim()}
                className="group/btn w-8 h-8 bg-black/60 backdrop-blur-md text-white rounded-[12px] transition-all flex items-center justify-center shadow-lg disabled:opacity-30 disabled:cursor-not-allowed"
              >
                <Icon name="refresh" size={20} className="opacity-[0.48] group-hover/btn:opacity-100 transition-opacity" />
              </button>
            </Tooltip>
            <Tooltip text="Delete frame">
              <button 
                onClick={(e) => {
                  e.stopPropagation();
                  onDelete(frame.id);
                }}
                className="group/btn w-8 h-8 bg-black/60 backdrop-blur-md text-white rounded-[12px] transition-all flex items-center justify-center shadow-lg"
              >
                <Icon name="delete" size={20} className="opacity-[0.48] group-hover/btn:opacity-100 transition-opacity" />
              </button>
            </Tooltip>
          </div>
        )}
      </div>

      {/* Label Area */}
      <div className="flex items-baseline gap-2.5 px-1 overflow-hidden w-full">
        <span className="text-[13px] font-bold text-[#DADCE0]/[0.48] font-sans shrink-0 leading-none">
          {frame.shotNumber.toString().padStart(2, '0')}
        </span>
        <div className="flex-1 flex items-center gap-1.5 min-w-0">
          <h3 className="text-[14px] font-bold text-white/90 truncate font-sans leading-none">
            {frame.title || 'Frame title'}
          </h3>
          <Icon name="edit" size={26} className="opacity-0 group-hover:opacity-[0.48] transition-opacity flex-shrink-0 p-1" />
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { StoryboardFrame, Asset, VisualStyle, CharacterAsset, LocationAsset, PropAsset } from '../types';
import { Icon } from './Icon';
import { PillButton } from './DesignSystem';
import { Tooltip } from './Tooltip';

const Loader2: React.FC<{ size?: number; className?: string }> = ({ size = 16, className = '' }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`animate-spin ${className}`}><path d="M21 12a9 9 0 1 1-6.219-8.56" /></svg>
);

/** Returns the best available thumbnail URL for an asset */
const getAssetThumbnail = (asset: Asset): string | undefined => {
  const hero = asset.supportingImages.find(img => img.id === asset.referenceImageId) || asset.supportingImages[0];
  return hero?.dataUrl || asset.imageUrl;
};

/** Icon name for the asset type fallback */
const assetTypeIcon = (type: Asset['type']): string =>
  type === 'location' ? 'map' : type === 'prop' ? 'deployed_code' : 'person';

interface FrameEditPanelProps {
  frame: StoryboardFrame | null;
  frames: StoryboardFrame[];
  assets: Asset[];
  script?: string;
  style: VisualStyle;
  customStyleLibrary: Record<string, string>;
  onStyleChange: (style: VisualStyle) => void;
  aspectRatio: '16:9' | '9:16';
  onUpdate: (id: string, updates: Partial<StoryboardFrame>) => void;
  onDelete: (id: string) => void;
  onGenerate: (id: string, forcedFrame?: StoryboardFrame, forcedStyle?: VisualStyle) => Promise<void>;
  onSelectFrame: (id: string | null) => void;
  isGenerating: boolean;
  onOpenCustomStyleModal?: (editingName?: string) => void;
  onRemoveCustomStyle?: (name: string) => void;
  onExpand?: () => void;
}

export const FrameEditPanel: React.FC<FrameEditPanelProps> = ({
  frame, assets, script = '', style, customStyleLibrary, onStyleChange, aspectRatio, onUpdate, onDelete, onGenerate, onSelectFrame, isGenerating, onOpenCustomStyleModal, onRemoveCustomStyle, onExpand
}) => {
  const [showAssetPicker, setShowAssetPicker] = useState(false);
  const [assetPickerPosition, setAssetPickerPosition] = useState<{ top: number; left: number } | null>(null);
  const [isRefreshingAssets, setIsRefreshingAssets] = useState(false);
  const [imageToDeleteUrl, setImageToDeleteUrl] = useState<string | null>(null);

  const addAssetButtonRef = useRef<HTMLButtonElement>(null);
  const assetPickerRef = useRef<HTMLDivElement>(null);
  const portalContentRef = useRef<HTMLDivElement>(null);

  // Close asset picker on outside click
  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (
        showAssetPicker &&
        assetPickerRef.current && !assetPickerRef.current.contains(e.target as Node) &&
        (!portalContentRef.current || !portalContentRef.current.contains(e.target as Node))
      ) {
        setShowAssetPicker(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showAssetPicker]);

  // Close on scroll to prevent disconnected positioning (but allow internal scrolling)
  useEffect(() => {
    if (!showAssetPicker) return;
    const handleScroll = (e: Event) => {
      if (portalContentRef.current && portalContentRef.current.contains(e.target as Node)) {
        return;
      }
      setShowAssetPicker(false);
    };
    window.addEventListener('scroll', handleScroll, true);
    return () => window.removeEventListener('scroll', handleScroll, true);
  }, [showAssetPicker]);

  const handleToggleAssetPicker = () => {
    if (!showAssetPicker && addAssetButtonRef.current) {
      const rect = addAssetButtonRef.current.getBoundingClientRect();
      const popupWidth = 300;
      const modalRoot = document.getElementById('story-studio-modal-root');
      const rootRect = modalRoot ? modalRoot.getBoundingClientRect() : { top: 0, left: 0 };
      // Anchor below-right of the button, clamped to viewport
      const left = Math.min(rect.right - popupWidth, window.innerWidth - popupWidth - 12);
      setAssetPickerPosition({ top: rect.bottom + 8 - rootRect.top, left: Math.max(12, left) - rootRect.left });
    }
    setShowAssetPicker(prev => !prev);
  };

  const handleRefreshAssets = async () => {
    if (!frame || !script.trim()) return;
    setIsRefreshingAssets(true);
    try {
      // Analyze the script context for the current frame to detect mentioned assets
      const lowerVisual = (frame.visualDescription || '').toLowerCase();
      const lowerTitle = (frame.title || '').toLowerCase();

      const newlyDetectedIds = assets
        .filter(asset => {
          const name = asset.name.toLowerCase();
          return lowerVisual.includes(name) || lowerTitle.includes(name);
        })
        .map(a => a.id);

      // Add a small delay so the user can see the spin effect (purely for UX feedback)
      await new Promise(resolve => setTimeout(resolve, 800));

      if (newlyDetectedIds.length > 0) {
        const currentIds = frame.linkedAssetIds || [];
        const merged = Array.from(new Set([...currentIds, ...newlyDetectedIds]));
        onUpdate(frame.id, { linkedAssetIds: merged });
      }
    } finally {
      setIsRefreshingAssets(false);
    }
  };

  const handleDeleteImage = (url: string) => {
    if (!frame) return;
    if (url?.startsWith('blob:')) {
      URL.revokeObjectURL(url);
    }
    const newHistory = frame.imageHistory?.filter(u => u !== url) || [];
    onUpdate(frame.id, { imageHistory: newHistory });
    if (frame.imageUrl === url) {
      onUpdate(frame.id, { imageUrl: newHistory[0] || '' });
    }
  };

  const promoteImage = (url: string) => {
    if (!frame) return;
    onUpdate(frame.id, { imageUrl: url });
  };

  const linkedAssets = useMemo(() => {
    if (!frame) return [];
    return assets.filter(a => frame.linkedAssetIds?.includes(a.id));
  }, [assets, frame?.linkedAssetIds]);

  if (!frame) return null;

  return (
    <div className="w-full flex flex-col h-full relative z-50 bg-[#000000]">
      <button
        onClick={() => onSelectFrame(null)}
        className="absolute top-4 right-4 z-50 w-8 h-8 flex items-center justify-center rounded-full bg-black/40 hover:bg-black/60 transition-all"
        title="Close panel"
      >
        <Icon name="close" size={20} className="opacity-[0.48]" />
      </button>
      <div className="flex-1 overflow-y-auto px-6 pt-10 pb-10 space-y-6 refined-scrollbar">
        <div className="flex flex-col gap-0.5">
          <label className="text-[11px] font-medium text-[#DADCE0]/[0.48] font-sans px-1">
            Scene {frame.sceneNumber} • Frame {frame.shotNumber}
          </label>
          <input
            value={frame.title}
            onChange={(e) => onUpdate(frame.id, { title: e.target.value })}
            className="w-full bg-transparent border border-[#DADCE0]/[0.40] hover:border-white/20 focus:border-white/30 rounded-[8px] py-[0.4rem] px-3 text-[13px] font-flex text-white/90 focus:outline-none transition-all placeholder:text-white/[0.38]"
            placeholder="Frame title"
          />
        </div>

        <div className="flex flex-col gap-0.5">
          <label className="text-[12px] font-medium text-[#DADCE0]/[0.48] font-sans ml-1">Frame Description</label>
          <textarea
            value={frame.visualDescription}
            onChange={(e) => onUpdate(frame.id, { visualDescription: e.target.value })}
            className="border border-[#DADCE0]/[0.40] hover:border-white/20 focus:border-white/30 rounded-[8px] w-full h-[140px] px-3 py-[0.4rem] resize-none bg-transparent text-[13px] font-flex text-white/90 focus:outline-none transition-colors leading-relaxed placeholder:text-white/[0.38]"
            placeholder="Describe the visual composition..."
          />
        </div>

        <div className="flex flex-col gap-0.5" ref={assetPickerRef}>
          <div className="flex items-center justify-between px-1">
            <label className="text-[12px] font-medium text-[#DADCE0]/[0.48] font-sans">Reference Assets</label>
            <div className="flex items-center gap-2">
              <button
                onClick={handleRefreshAssets}
                disabled={isRefreshingAssets}
                className="w-8 h-8 flex items-center justify-center hover:bg-white/5 rounded-lg transition-colors disabled:opacity-30"
                title="Auto-detect from script"
              >
                <Icon name="refresh" size={20} className={`opacity-[0.48] ${isRefreshingAssets ? 'animate-spin' : ''}`} />
              </button>
              <button
                ref={addAssetButtonRef}
                onClick={handleToggleAssetPicker}
                className={`w-8 h-8 flex items-center justify-center rounded-lg transition-colors ${showAssetPicker ? 'bg-white/10' : 'hover:bg-white/5'}`}
                title="Add Asset"
              >
                <Icon name="add" size={20} className="opacity-[0.48]" />
              </button>
            </div>
          </div>

          <div className="flex flex-wrap gap-2">
            {linkedAssets.length === 0 ? (
              <div className="w-full flex items-center justify-center text-[12px] text-white/[0.38] font-medium italic py-4">
                No assets selected
              </div>
            ) : (
              linkedAssets.map(asset => {
                const thumb = getAssetThumbnail(asset);
                return (
                  <div key={asset.id} className="h-[36px] border border-[#DADCE0]/[0.40] rounded-lg flex items-center gap-2 group hover:border-[#DADCE0]/[0.60] transition-all overflow-hidden">
                    <div className="h-full aspect-video bg-white/10 flex items-center justify-center overflow-hidden border-r border-[#DADCE0]/[0.16]">
                      {thumb ? (
                        <img src={thumb} className="w-full h-full object-cover" />
                      ) : (
                        <Icon name={assetTypeIcon(asset.type)} size={20} className="opacity-[0.48]" />
                      )}
                    </div>
                    <span className="text-[13px] font-medium text-white/90 px-1">{asset.name}</span>
                    <button
                      onClick={() => onUpdate(frame.id, { linkedAssetIds: (frame.linkedAssetIds || []).filter(id => id !== asset.id) })}
                      className="opacity-40 hover:opacity-100 transition-opacity mr-2"
                    >
                      <Icon name="close" size={20} className="opacity-[0.48]" />
                    </button>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Style + Image Generation + Thumbnails — combined section */}
        <div className="flex flex-col gap-2">
          <div className="flex items-center justify-center gap-3">
            <PillButton
              variant="outline"
              onClick={() => onGenerate(frame.id, undefined, style)}
              disabled={isGenerating}
              className="border-[#DADCE0]/[0.40] text-white/90 font-bold px-3 py-[0.4rem] text-[13px]"
            >
              Create image
            </PillButton>
          </div>

          {/* Hero Image Preview */}
          <div className={`bg-[#DADCE0]/[0.04] border border-[#DADCE0]/[0.24] rounded-[12px] overflow-hidden flex items-center justify-center relative group shadow-inner ${aspectRatio === '9:16' ? 'aspect-[9/16]' : 'aspect-video'}`}>
            {frame.imageUrl ? (
              <>
                <img src={frame.imageUrl} className="w-full h-full object-cover" />
                <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-all duration-200 flex gap-2 z-30">
                  {onExpand && (
                    <Tooltip text="View full size">
                      <button 
                        onClick={(e) => { e.stopPropagation(); onExpand(); }}
                        className="group/btn w-8 h-8 bg-black/60 backdrop-blur-md rounded-[12px] transition-all flex items-center justify-center shadow-lg"
                      >
                        <Icon name="open_in_full" size={18} className="opacity-[0.48] group-hover/btn:opacity-100 transition-opacity" />
                      </button>
                    </Tooltip>
                  )}
                  <Tooltip text="Delete image">
                    <button 
                      onClick={(e) => { e.stopPropagation(); setImageToDeleteUrl(frame.imageUrl!); }}
                      className="group/btn w-8 h-8 bg-black/60 backdrop-blur-md text-white rounded-[12px] transition-all flex items-center justify-center shadow-lg"
                    >
                      <Icon name="delete" size={20} className="opacity-[0.48] group-hover/btn:opacity-100 transition-opacity" />
                    </button>
                  </Tooltip>
                </div>
              </>
            ) : (
              <Icon name="image" size={40} className="opacity-[0.16]" />
            )}

            {isGenerating && (
              <div className="absolute inset-0 bg-black/60 backdrop-blur-sm rounded-[12px] z-20 flex items-center justify-center">
                <div className="flex gap-1.5 items-center">
                  <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce [animation-delay:-0.3s]" />
                  <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce [animation-delay:-0.15s]" />
                  <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce" />
                </div>
              </div>
            )}
          </div>

          {/* Image History Thumbnails */}
          {frame.imageHistory && frame.imageHistory.length > 0 && (
            <div className="flex flex-wrap gap-3">
              {frame.imageHistory.map((url, idx) => {
                const isActive = frame.imageUrl === url;
                return (
                  <div
                    key={idx}
                    className={`relative h-[60px] aspect-video rounded-[12px] overflow-hidden transition-all group cursor-pointer ${isActive ? 'border-2 border-white opacity-100' : 'opacity-60 hover:opacity-100 border border-[#DADCE0]/[0.24]'}`}
                  >
                    <button onClick={() => promoteImage(url)} className="w-full h-full">
                      <img src={url} className="w-full h-full object-contain bg-zinc-900 rounded-[6px]" />
                    </button>

                    <div className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 transition-opacity z-20" onClick={e => e.stopPropagation()}>
                      <button
                        onClick={(e) => { e.stopPropagation(); setImageToDeleteUrl(url); }}
                        className="group/btn w-8 h-8 bg-black/60 backdrop-blur-md text-white rounded-[12px] flex items-center justify-center transition-all shadow-lg"
                      >
                        <Icon name="delete" size={20} className="opacity-[0.48] group-hover/btn:opacity-100 transition-opacity" />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* Asset Picker Popup (portal-based, matching StyleSelector pattern) */}
      {showAssetPicker && assetPickerPosition && createPortal(
        <div className="absolute inset-0 z-[200] pointer-events-auto" onClick={() => setShowAssetPicker(false)}>
        <div
          ref={portalContentRef}
          style={{ top: assetPickerPosition.top, left: assetPickerPosition.left }}
          className="absolute w-[300px] bg-[#000000] border border-[#DADCE0]/[0.24] rounded-[12px] shadow-2xl z-[200] animate-dropdown origin-top-right py-2"
          onClick={e => e.stopPropagation()}
        >
          <div className="px-4 pt-2 pb-1">
            <span className="text-[12px] font-bold text-white/50 font-sans tracking-wider">Select Assets</span>
          </div>
          <div className="max-h-[320px] overflow-y-auto refined-scrollbar">
            {assets.length === 0 ? (
              <div className="px-4 py-6 text-center text-[13px] text-white/[0.38] font-sans italic">
                No assets available
              </div>
            ) : (
              (['character', 'location', 'prop'] as const).map(type => {
                const filteredAssets = assets.filter(a => a.type === type);
                if (filteredAssets.length === 0) return null;

                const typeLabels: Record<string, string> = {
                  character: 'Characters',
                  location: 'Locations',
                  prop: 'Props'
                };

                return (
                  <div key={type} className="space-y-1 mb-3 last:mb-1">
                    <div className="px-4 py-1 bg-white/[0.02]">
                      <span className="text-[11px] font-bold text-white/30 font-sans tracking-wider">{typeLabels[type]}</span>
                    </div>
                    {filteredAssets.map(asset => {
                      const isChecked = frame.linkedAssetIds?.includes(asset.id) ?? false;
                      const thumb = getAssetThumbnail(asset);
                      return (
                        <label
                          key={asset.id}
                          className={`flex items-center gap-3 px-3 py-2 cursor-pointer transition-all hover:bg-white/5 ${isChecked ? 'bg-white/[0.03]' : ''}`}
                        >
                          <input
                            type="checkbox"
                            checked={isChecked}
                            onChange={(e) => {
                              const current = frame.linkedAssetIds || [];
                              const next = e.target.checked ? [...current, asset.id] : current.filter(id => id !== asset.id);
                              onUpdate(frame.id, { linkedAssetIds: next });
                            }}
                            className="w-[18px] h-[18px] accent-white rounded border-white/10 bg-transparent flex-shrink-0"
                          />
                          <div className="w-[64px] h-[36px] rounded-[4px] bg-white/5 border border-white/[0.08] flex items-center justify-center overflow-hidden flex-shrink-0">
                            {thumb ? (
                              <img src={thumb} className="w-full h-full object-cover" />
                            ) : (
                              <Icon name={assetTypeIcon(asset.type)} size={20} className="opacity-[0.38]" />
                            )}
                          </div>
                          <div className="flex flex-col min-w-0">
                            <span className="text-[13px] font-medium text-white/90 font-sans truncate">{asset.name}</span>
                            <span className="text-[11px] text-white/[0.38] font-sans capitalize">{asset.type}</span>
                          </div>
                        </label>
                      );
                    })}
                  </div>
                );
              })
            )}
          </div>
        </div>
        </div>,
        document.getElementById('story-studio-modal-root') || document.body
      )}

      {imageToDeleteUrl && createPortal(
        <div className="absolute inset-0 z-[200] flex items-center justify-center p-6 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200 pointer-events-auto" onClick={() => setImageToDeleteUrl(null)}>
          <div className="bg-black border border-[rgba(218,220,224,0.15)] w-full max-w-[380px] rounded-[24px] p-6 pt-8 shadow-2xl text-center space-y-6 animate-in zoom-in-95 duration-300" onClick={e => e.stopPropagation()}>
            <Icon name="delete" size={48} className="opacity-[0.24] mx-auto" />
            <div>
              <h3 className="text-[18px] font-bold text-white font-sans tracking-tight mb-2">Delete image</h3>
              <p className="text-[14px] text-zinc-500 font-sans">This action cannot be undone.</p>
            </div>
            <div className="flex gap-3 pt-2">
              <button onClick={() => setImageToDeleteUrl(null)} className="flex-1 h-10 rounded-full border border-[#595959] text-[rgba(218,220,224,0.9)] font-bold hover:border-zinc-400 transition-all font-sans text-[13px]">Cancel</button>
              <button 
                onClick={() => { handleDeleteImage(imageToDeleteUrl); setImageToDeleteUrl(null); }} 
                className="flex-1 h-10 rounded-full bg-[#DADCE0]/[0.72] text-black/90 font-bold hover:bg-white transition-all font-sans text-[13px]"
              >
                Delete
              </button>
            </div>
          </div>
        </div>,
        document.getElementById('story-studio-modal-root') || document.body
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';

interface GenerationQueueToastProps {
  completed: number;
  total: number;
  failed: number;
  onStop: () => void;
  onDismiss: () => void;
}

export const GenerationQueueToast: React.FC<GenerationQueueToastProps> = ({
  completed,
  total,
  failed,
  onStop,
  onDismiss
}) => {
  const [isDismissing, setIsDismissing] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  const isFinished = completed + failed >= total;

  // Entrance animation
  useEffect(() => {
    const timer = setTimeout(() => setIsVisible(true), 50);
    return () => clearTimeout(timer);
  }, []);

  // Auto-dismiss 2s after everything finishes
  useEffect(() => {
    if (!isFinished) return;
    const timer = setTimeout(() => {
      setIsDismissing(true);
      // Wait for fade-out animation before unmounting
      setTimeout(() => onDismiss(), 400);
    }, 2000);
    return () => clearTimeout(timer);
  }, [isFinished, onDismiss]);

  const progress = total > 0 ? ((completed + failed) / total) * 100 : 0;

  return (
    <div 
      className={`fixed bottom-6 left-1/2 -translate-x-1/2 z-[150] transition-all duration-300 ${
        isVisible && !isDismissing ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'
      }`}
    >
      <div className="flex items-center gap-4 bg-black border border-[#DADCE0]/[0.24] rounded-2xl px-5 py-3 shadow-2xl min-w-[280px]">
        {/* Progress indicator */}
        {!isFinished ? (
          <div className="flex gap-1 items-center shrink-0">
            <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce [animation-delay:-0.3s]" />
            <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce [animation-delay:-0.15s]" />
            <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce" />
          </div>
        ) : (
          <svg width={16} height={16} viewBox="0 0 16 16" className="shrink-0 text-white">
            <path d="M6.5 11.5L3 8l1-1 2.5 2.5L12 4l1 1z" fill="currentColor" />
          </svg>
        )}

        {/* Status text */}
        <div className="flex items-center gap-2 flex-1 min-w-0">
          <span className="text-[13px] font-bold text-white font-sans whitespace-nowrap">
            {isFinished ? 'Complete' : 'Generating images'}
          </span>
          <span className="text-[13px] text-zinc-500 font-sans whitespace-nowrap">
            {completed}{failed > 0 ? ` · ${failed} failed` : ''} / {total}
          </span>
        </div>

        {/* Progress bar */}
        <div className="w-16 h-1 bg-white/10 rounded-full overflow-hidden shrink-0">
          <div 
            className="h-full bg-white rounded-full transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          />
        </div>

        {/* Stop / Done button */}
        {!isFinished && (
          <button
            onClick={(e) => { e.stopPropagation(); onStop(); }}
            className="text-[13px] font-bold text-zinc-400 hover:text-white transition-colors font-sans shrink-0 px-2 py-1 rounded-lg hover:bg-white/5"
          >
            Stop
          </button>
        )}
      </div>
    </div>
  );
};

import React from 'react';

interface IconProps {
  name: string;
  size?: number;
  className?: string;
  invert?: boolean;
}

export const Icon: React.FC<IconProps> = ({ name, size = 20, className = "", invert = true }) => {
  // Map internal icon names to the specific requested SVG path format
  // Mapping 'auto_awesome' to 'spark' as requested by the user
  const iconName = name === 'auto_awesome' ? 'spark' : name;
  const src = `https://fonts.gstatic.com/s/i/short-term/release/googlesymbols/${iconName}/default/24px.svg`;

  // Check if a specific opacity is already provided in the className to avoid double-application
  const hasOpacity = className.includes('opacity-');

  return (
    <img 
      src={src} 
      alt={name}
      className={`select-none pointer-events-none inline-block ${!hasOpacity ? 'opacity-60' : ''} ${className}`}
      style={{ 
        width: `${size}px`,
        height: `${size}px`,
        // Icons are black by default; invert them for dark mode unless specified (e.g. for light surfaces)
        filter: invert ? 'invert(1)' : 'none' 
      }}
    />
  );
};

import React, { useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { Icon } from './Icon';

interface LightboxItem {
  id: string;
  imageUrl: string;
  label: string;
}

interface ImageLightboxProps {
  items: LightboxItem[];
  activeIndex: number;
  onClose: () => void;
  onNavigate: (index: number) => void;
}

export const ImageLightbox: React.FC<ImageLightboxProps> = ({ items, activeIndex, onClose, onNavigate }) => {
  const item = items[activeIndex];
  const hasPrev = activeIndex > 0;
  const hasNext = activeIndex < items.length - 1;

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (e.key === 'Escape') onClose();
    if (e.key === 'ArrowLeft' && hasPrev) onNavigate(activeIndex - 1);
    if (e.key === 'ArrowRight' && hasNext) onNavigate(activeIndex + 1);
  }, [onClose, onNavigate, activeIndex, hasPrev, hasNext]);

  useEffect(() => {
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  if (!item) return null;

  return createPortal(
    <div
      className="absolute inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-sm pointer-events-auto"
      onClick={onClose}
    >
      {/* Close button */}
      <button
        onClick={onClose}
        className="absolute top-5 right-5 z-10 w-10 h-10 flex items-center justify-center rounded-full bg-black/60 backdrop-blur-md hover:bg-white/10 transition-all"
      >
        <Icon name="close" size={22} className="text-white/80" />
      </button>

      {/* Navigation: Previous */}
      {hasPrev && (
        <button
          onClick={(e) => { e.stopPropagation(); onNavigate(activeIndex - 1); }}
          className="absolute left-5 top-1/2 -translate-y-1/2 z-10 w-12 h-12 flex items-center justify-center rounded-full bg-black/60 backdrop-blur-md hover:bg-white/10 transition-all"
        >
          <Icon name="chevron_left" size={28} className="text-white/80" />
        </button>
      )}

      {/* Navigation: Next */}
      {hasNext && (
        <button
          onClick={(e) => { e.stopPropagation(); onNavigate(activeIndex + 1); }}
          className="absolute right-5 top-1/2 -translate-y-1/2 z-10 w-12 h-12 flex items-center justify-center rounded-full bg-black/60 backdrop-blur-md hover:bg-white/10 transition-all"
        >
          <Icon name="chevron_right" size={28} className="text-white/80" />
        </button>
      )}

      {/* Image */}
      <div className="max-w-[90vw] max-h-[85vh] flex flex-col items-center gap-4" onClick={e => e.stopPropagation()}>
        <img
          src={item.imageUrl}
          alt={item.label}
          className="max-w-full max-h-[80vh] object-contain rounded-lg shadow-2xl"
        />
        <div className="flex items-center gap-3">
          <span className="text-[14px] font-medium text-white/80 font-sans">{item.label}</span>
          <span className="text-[13px] text-white/40 font-sans">{activeIndex + 1} / {items.length}</span>
        </div>
      </div>
    </div>,
    document.getElementById('story-studio-modal-root') || document.body
  );
};

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { useEditor } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import Heading from '@tiptap/extension-heading';
import Placeholder from '@tiptap/extension-placeholder';
import Underline from '@tiptap/extension-underline';
import { Plugin } from '@tiptap/pm/state';
import Editor from './Editor';
import Toolbar from './Toolbar';
import { ScriptScene, ScriptContext, Asset, CharacterAsset, LocationAsset, PropAsset } from '../types';
import { parseScriptToScenes, joinScenes, validateAndCleanScenes } from '../services/sceneParser';
import { Flow } from 'flow-sdk';
import { turndownService } from '../services/turndown';
import { Icon } from './Icon';

const Loader2: React.FC<{ size?: number; className?: string }> = ({ size = 16, className = '' }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`animate-spin ${className}`}><path d="M21 12a9 9 0 1 1-6.219-8.56" /></svg>
);

/** Generate a stable scene UUID */
const generateSceneId = () => {
  try {
    return `scene-${crypto.randomUUID()}`;
  } catch (e) {
    return `scene-${Math.random().toString(36).substring(2, 15)}${Date.now().toString(36)}`;
  }
};

const CustomHeading = Heading.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      'scene-id': {
        default: null,
        parseHTML: element => element.getAttribute('data-scene-id'),
        renderHTML: attributes => {
          if (!attributes['scene-id']) return {};
          return { 'data-scene-id': attributes['scene-id'] };
        },
      },
      id: {
        default: null,
        parseHTML: element => element.getAttribute('id'),
        renderHTML: attributes => {
          if (!attributes.id) return {};
          return { id: attributes.id };
        },
      },
    };
  },

  addProseMirrorPlugins() {
    return [
      new Plugin({
        // Auto-assign a stable scene-id to any H3 heading that doesn't have one,
        // AND fix duplicates (e.g. from copy-paste which preserves attributes).
        appendTransaction(_transactions, _oldState, newState) {
          // Skip traversal on cursor-only movements — only process when doc changed
          if (!_transactions.some(tr => tr.docChanged)) return null;
          let tr: ReturnType<typeof newState.tr.setNodeMarkup> | null = null;
          const seenIds = new Set<string>();
          newState.doc.descendants((node, pos) => {
            if (node.type.name === 'heading' && node.attrs.level === 3) {
              const existingId = node.attrs['scene-id'];
              if (!existingId || seenIds.has(existingId)) {
                // Missing ID or duplicate (from copy-paste) — assign a fresh one
                if (!tr) tr = newState.tr;
                const newId = generateSceneId();
                tr.setNodeMarkup(pos, undefined, {
                  ...node.attrs,
                  'scene-id': newId,
                  id: newId,
                });
                seenIds.add(newId);
              } else {
                seenIds.add(existingId);
              }
            }
          });
          return tr;
        },
      }),
    ];
  },
});

interface ScriptViewProps {
  onTitleChange?: (title: string) => void;
  fullMarkdown: string;
  onMarkdownChange: (markdown: string) => void;
  assets?: Asset[];
  globalStyle?: string;
  onGlobalStyleChange?: (style: string) => void;
  customStyleLibrary?: Record<string, string>;
  onOpenCustomStyleModal?: (editingName?: string) => void;
  onRemoveCustomStyle?: (name: string) => void;
}

export function ScriptView({ onTitleChange, fullMarkdown, onMarkdownChange, assets = [], globalStyle = 'Realistic', onGlobalStyleChange, customStyleLibrary = {}, onOpenCustomStyleModal, onRemoveCustomStyle }: ScriptViewProps) {
  const [scenes, setScenes] = useState<ScriptScene[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [scriptFont, setScriptFont] = useState<'helvetica' | 'courier'>('helvetica');
  const [agentPrompt, setAgentPrompt] = useState('');
  const agentTextareaRef = useRef<HTMLTextAreaElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Build asset context string from pre-created assets
  const assetContextString = useMemo(() => {
    if (assets.length === 0) return '';
    const formatAsset = (a: Asset) => {
      const parts = [`- ${a.name} (${a.type})`];
      const desc = (a as CharacterAsset | LocationAsset | PropAsset).physicalCharacteristics;
      if (desc) parts.push(`  Description: ${desc}`);
      if (a.type === 'character') {
        const ca = a as CharacterAsset;
        if (ca.clothingAccessories) parts.push(`  Clothing: ${ca.clothingAccessories}`);
        if (ca.backstory) parts.push(`  Backstory: ${ca.backstory}`);
      }
      if (a.type === 'location') {
        const la = a as LocationAsset;
        if (la.timeOfDay) parts.push(`  Time of Day: ${la.timeOfDay}`);
      }
      return parts.join('\x0a');
    };
    const chars = assets.filter(a => a.type === 'character').map(formatAsset).join('\x0a');
    const locs = assets.filter(a => a.type === 'location').map(formatAsset).join('\x0a');
    const props = assets.filter(a => a.type === 'prop').map(formatAsset).join('\x0a');
    const sections = [];
    if (chars) sections.push(`Characters:\x0a${chars}`);
    if (locs) sections.push(`Locations:\x0a${locs}`);
    if (props) sections.push(`Props:\x0a${props}`);
    return sections.join('\x0a\x0a');
  }, [assets]);

  const [context, setContext] = useState<ScriptContext>({ brief: '', scratchpad: '', assets: '' });

  useEffect(() => {
    const parsed = parseScriptToScenes(fullMarkdown);
    const cleaned = validateAndCleanScenes(parsed);
    setScenes(cleaned);
  }, [fullMarkdown]);


  const isHydratedRef = useRef(false);

  const editor = useEditor({
    autofocus: true,
    extensions: [
      StarterKit.configure({ heading: false }),
      CustomHeading.configure({ levels: [1, 2, 3, 5] }),
      Underline,
      Placeholder.configure({
        placeholder: 'Write your script or prompt story ideas below...',
        emptyEditorClass: 'is-editor-empty',
      }),
    ],
    content: '',
    editorProps: {
      attributes: {
        class: 'prose prose-invert max-w-none focus:outline-none min-h-[80vh] cursor-text',
      },
    },
    onUpdate: ({ editor }) => {
      const html = editor.getHTML();
      const markdown = turndownService.turndown(html);

      // Extract title from markdown (first # Heading)
      const titleMatch = markdown.match(/^#\s+(.*)$/m);
      if (titleMatch && onTitleChange) {
        onTitleChange(titleMatch[1].trim());
      } else if (!titleMatch && onTitleChange) {
        onTitleChange('Untitled Story');
      }

      // Only update the parent if we've already hydrated from the parent once
      if (isHydratedRef.current) {
        onMarkdownChange(markdown);
      }
    },
  });

  useEffect(() => {
    let isMounted = true;
    if (editor && fullMarkdown && !isHydratedRef.current) {
      const timer = setTimeout(() => {
        if (!isMounted || !editor || editor.isDestroyed) return;
        isHydratedRef.current = true;
      }, 50);
      return () => {
        isMounted = false;
        clearTimeout(timer);
      };
    } else if (editor && !fullMarkdown && !isHydratedRef.current) {
      isHydratedRef.current = true;
    }
    return () => { isMounted = false; };
  }, [editor, fullMarkdown]);

  // Handle clicks on the blockquote X (::after) button to remove comment styling
  useEffect(() => {
    const scrollEl = scrollContainerRef.current;
    if (!scrollEl || !editor) return;

    const handleClick = (e: MouseEvent) => {
      if (!editor || editor.isDestroyed) return;

      const target = e.target as HTMLElement;
      const bq = target.closest('blockquote');
      if (!bq) return;

      const rect = bq.getBoundingClientRect();
      const clickX = e.clientX;
      const clickY = e.clientY;
      // Check if click is in the top-right area where the X button is (20x20 at top:8 right:8)
      if (clickX >= rect.right - 28 && clickY <= rect.top + 28) {
        e.preventDefault();
        e.stopPropagation();

        try {
          // Find the blockquote node position and delete the entire block
          const pos = editor.view.posAtDOM(bq, 0);
          if (pos !== undefined) {
            const resolved = editor.state.doc.resolve(pos);
            // Walk up to find the blockquote node
            for (let d = resolved.depth; d > 0; d--) {
              if (resolved.node(d).type.name === 'blockquote') {
                const from = resolved.before(d);
                const to = resolved.after(d);
                editor.chain().focus().deleteRange({ from, to }).run();
                break;
              }
            }
          }
        } catch (err) {
          console.error('Failed to delete blockquote:', err);
        }
      }
    };

    scrollEl.addEventListener('click', handleClick);
    return () => scrollEl.removeEventListener('click', handleClick);
  }, [editor]);

  const isEmpty = !fullMarkdown || fullMarkdown.trim().length === 0;

  const handleAgentSubmit = async () => {
    if (!agentPrompt.trim() || isGenerating) return;

    const currentPrompt = agentPrompt;
    setAgentPrompt('');
    setIsGenerating(true);

    try {
      const systemInstruction = `## PERSONA:
You are an expert in screenplay writing, a specific Markdown convention for writing screenplays. For all screenplay-related tasks, you MUST adhere strictly to the following formatting rules without deviation.

${isEmpty ? `\x0a## ASSETS:\x0a${assetContextString || context.assets || 'None provided.'}\x0a${assetContextString ? 'IMPORTANT: The user has pre-created the above assets (characters, locations, props). When writing a NEW script, you MUST incorporate these assets naturally into the screenplay. Use the exact character names, locations, and props provided. Weave their descriptions and backstories into the narrative.' : ''}` : ''}

## CURRENT SCRIPT:
${fullMarkdown}

## SCREENPLAY CONVENTION RULES:
1.  **Title or Act Number**: The script must begin with a title page. The title page must be in all CAPS. If the script has acts, use the same visual treatment.
    *   **TITLE**: A Level 1 Header (#).
2.  **Scene Heading (Slugline)**: Use a Level 2 Header (###). The text MUST be in ALL CAPS.
    *   Example: ### INT. SPACESHIP COCKPIT - NIGHT
3.  **Action/Description**: Use standard paragraph text. This is the default format for describing scenes and character actions.
4.  **Character Names in Action Lines**: CRITICAL - Character names in action/description paragraphs follow specific rules:
    *   **First appearance only**: Normal weight and ALL CAPS (EVA) when a character first appears in the script
    *   **All subsequent appearances**: Title Case (Eva) without bold or ALL CAPS.
    *   Never use ALL CAPS for character names in action lines except for their first introduction
    *   Example: EVA enters the cockpit. Eva checks the controls.
5.  **Character Name** for Dialogue: Use bold all caps text (**CHARACTER**) when the character's name is used in dialogue. The name MUST be in ALL CAPS and appear on its own line directly above their dialogue.
    *   Example: **EVA**
    *   CRITICAL: Bold (**) must ONLY be used for character names before dialogue. NEVER use bold for emphasis, action text, comments, or any other purpose in the script.
6.  **Dialogue**: Must preceed a Character name or parenthetical and be on it's own line. Never add to line breaks between multiple lines of dialogue. Never use blockquotes (>) for dialogue. All lines of dialogue.
    *   Example: Get me a damage report.
7.  **Parenthetical**: Use italic text (_(text)_) enclosed in parentheses. It MUST be placed on its own line between the Character Name and the Dialogue block.
8.  **Transition**: Use a Level 5 Header (#####). The text MUST be in ALL CAPS and end with a colon.
    *   Example: ##### FADE TO BLACK:
    *   Example: ##### CUT TO:
9. **Non-script Notes**: To add notes, comments or additional information to the script, use blockquotes (> text). These will be removed from the final script. Note Titles are optional. Don't nest blockquotes. NEVER use bold in blockquote comments.

Estimate approximately 1 page per minute of screen time.

## CRITICAL EDITING INSTRUCTIONS:
- Make ONLY the specific changes requested in the feedback
- PRESERVE all content that is not being edited
- Preserve the scene heading format (### INT./EXT.)
- PRESERVE all existing blockquote comments (lines starting with >) unless explicitly asked to remove them
- PRESERVE all scene-id comments EXACTLY as they appear (e.g., <!-- scene-id: abc123 -->)
- NEVER generate, create, or modify scene-id comments - these are system-generated
- If the user asks to "clean up" or "format" the script, fix formatting issues to match the rules above
- Return the complete screenplay with edits applied
- NEVER escape Markdown characters in your output - use literal ** for bold, _ for italics, # for headers. Do not use backslash escaping like \\*\\* or \\_ in the screenplay text
- Include a diverse range of characters in your script. Try to use out of distribution, unique names for characters.
- NEVER use bold (**) for anything other than character names before dialogue lines. No bold in action lines, comments, or descriptions.

CRITICAL OUTPUT FORMATTING:
- NEVER escape Markdown characters in your output - use literal ** for bold, _ for italics, # for headers.
- NEVER generate, create, or add scene-id comments - these are system-generated.
- If the current script contains scene-id comments, DO NOT include them in new content you generate.
`;

      const { text: generatedText } = await Flow.generate.text(`${currentPrompt}`, { 
        systemInstruction,
        modelDisplayName: 'Gemini 3.0 Flash Preview',
        thinkingLevel: 'low'
      });

      if (editor && !editor.isDestroyed && generatedText) {
         onMarkdownChange(generatedText);

         const titleMatch = generatedText.match(/^#\s+(.*)$/m);
         if (titleMatch && onTitleChange) {
           onTitleChange(titleMatch[1].trim());
         }
      }
    } catch (err) {
      console.error('Agent failed:', err);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleEditorUpdate = useCallback((_markdown: string) => {
    // Handled by Tiptap onUpdate
  }, []);

  return (
    <div className="flex h-full w-full text-white overflow-hidden relative">
      <div className="flex-1 flex flex-col overflow-hidden relative">
        <div className="h-14 border-b border-[#DADCE0]/[0.16] z-30 flex items-center justify-center shrink-0">
          <div className="max-w-[800px] w-full">
            <Toolbar editor={editor} />
          </div>
        </div>

        <div 
          ref={scrollContainerRef}
          className="flex-1 overflow-y-auto dark-scrollbar relative scroll-smooth"
        >
          <div className={`max-w-[800px] mx-auto px-10 pt-[2.4em] pb-[160px] relative min-h-full ${scriptFont === 'courier' ? 'font-["Courier_Prime",_monospace]' : 'font-helvetica'}`}>

            <Editor 
              editor={editor}
              content={fullMarkdown} 
              onChange={handleEditorUpdate} 
            />
          </div>
        </div>

        <div className="absolute bottom-8 inset-x-0 mx-auto w-full max-w-2xl px-6 z-40 animate-dropdown">
          <div className="bg-[#000000] border border-[#595959] rounded-[16px] p-2 flex items-center shadow-2xl backdrop-blur-xl min-h-[56px]">
            <div className="px-4 py-1 flex-1 flex items-center gap-3">
              <textarea
                ref={agentTextareaRef}
                value={agentPrompt}
                onChange={(e) => setAgentPrompt(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    handleAgentSubmit();
                  }
                }}
                placeholder="Describe the story, edit scenes, update dialog..."
                className="w-full bg-transparent border-none text-[14px] text-white focus:outline-none placeholder-zinc-600 font-sans resize-none overflow-y-auto max-h-[120px] py-2"
                rows={1}
              />
            </div>
            <div className="flex items-center gap-2 pr-1.5">
              <button
                onClick={handleAgentSubmit}
                disabled={isGenerating || !agentPrompt.trim()}
                className="w-10 h-10 shrink-0 rounded-full flex items-center justify-center bg-[#424242] text-black hover:bg-[#505050] transition-all active:scale-95 disabled:opacity-40 shadow-lg"
              >
                <Icon name="arrow_forward" size={20} className="text-black opacity-100" />
              </button>
            </div>
          </div>
        </div>
      </div>

      {isGenerating && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/40 animate-in fade-in duration-300">
          <div className="bg-[#000000] border border-white/10 px-5 py-2.5 rounded-full shadow-2xl flex items-center gap-3">
            <Loader2 size={16} className="text-white animate-spin" />
            <h3 className="text-[12px] font-medium text-white tracking-[0.5px] font-sans">
              {isEmpty ? 'Writing Script...' : 'Editing Script...'}
            </h3>
          </div>
        </div>
      )}
    </div>
  );
}

import React from 'react';
