  );
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { Icon } from './Icon';
import { VISUAL_STYLE_PROMPTS } from '../services/ai';

interface StyleSelectorProps {
  globalStyle: string;
  onGlobalStyleChange: (style: string) => void;
  customStyleLibrary: Record<string, string>;
  onOpenCustomStyleModal?: (editingName?: string) => void;
  onRemoveCustomStyle?: (name: string) => void;
  hideLabel?: boolean;
}

export const StyleSelector: React.FC<StyleSelectorProps> = ({
  globalStyle,
  onGlobalStyleChange,
  customStyleLibrary,
  onOpenCustomStyleModal,
  onRemoveCustomStyle,
  hideLabel
}) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [menuPosition, setMenuPosition] = useState<{ top: number, left: number } | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const portalContentRef = useRef<HTMLDivElement>(null);

  const allStyleNames = useMemo(() => {
    return Array.from(new Set([
      ...Object.keys(customStyleLibrary),
      ...Object.keys(VISUAL_STYLE_PROMPTS)
    ])).sort();
  }, [customStyleLibrary]);

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      if (
        menuRef.current && !menuRef.current.contains(e.target as Node) &&
        (!portalContentRef.current || !portalContentRef.current.contains(e.target as Node))
      ) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  // Close menu on scroll to prevent disconnected positioning
  useEffect(() => {
    const handleScroll = () => setIsMenuOpen(false);
    window.addEventListener('scroll', handleScroll, true);
    return () => window.removeEventListener('scroll', handleScroll, true);
  }, []);

  const handleToggleMenu = () => {
    if (!isMenuOpen && buttonRef.current) {
      const rect = buttonRef.current.getBoundingClientRect();
      const modalRoot = document.getElementById('story-studio-modal-root');
      const rootRect = modalRoot ? modalRoot.getBoundingClientRect() : { top: 0, left: 0 };
      // Position aligned to the right edge of the button, similar to top-full mt-2 right-0
      setMenuPosition({ 
        top: rect.bottom + 8 - rootRect.top, 
        left: rect.right - 220 - rootRect.left // 220 is the width of the menu
      });
    }
    setIsMenuOpen(!isMenuOpen);
  };

  return (
    <div className="flex items-center gap-2.5 relative" ref={menuRef}>
      {!hideLabel && <span className="text-[13px] font-medium text-[#DADCE0]/[0.48] font-sans hidden md:inline">Style</span>}
      <button 
        ref={buttonRef}
        onClick={handleToggleMenu}
        className={`h-[36px] px-4 rounded-[8px] border border-[#DADCE0]/[0.40] flex items-center justify-between gap-3 text-[13px] font-bold transition-all ${
          isMenuOpen ? 'bg-zinc-800 border-white/20' : 'bg-transparent hover:bg-white/5'
        }`}
      >
        <span className="text-white truncate">{globalStyle}</span>
        <Icon name="expand_more" size={20} className={`opacity-[0.48] transition-transform ${isMenuOpen ? 'rotate-180' : ''}`} />
      </button>

      {isMenuOpen && menuPosition && createPortal(
        <div 
          ref={portalContentRef}
          style={{ top: menuPosition.top, left: menuPosition.left }}
          className="fixed w-[220px] bg-[#000000] border border-[#DADCE0]/[0.24] rounded-[8px] shadow-2xl overflow-hidden z-[200] animate-dropdown origin-top-right py-2"
        >
          {onOpenCustomStyleModal && (
            <>
              <button
                onClick={() => {
                  onOpenCustomStyleModal();
                  setIsMenuOpen(false);
                }}
                className="w-full px-5 py-3 text-left text-[12px] font-bold text-zinc-400 hover:text-white hover:bg-white/5 flex items-center gap-3 transition-colors"
              >
                <Icon name="add" size={20} className="opacity-[0.48]" />
                Create custom style
              </button>
              <div className="h-px bg-white/5 my-1 mx-2" />
            </>
          )}

          {allStyleNames.map(style => {
            const isCustom = style in customStyleLibrary;
            const isSelected = globalStyle === style;

            return (
              <div key={style} className="group relative">
                <button
                  onClick={() => {
                    onGlobalStyleChange(style);
                    setIsMenuOpen(false);
                  }}
                  className={`w-full pl-5 py-2.5 text-left text-[12px] font-bold flex items-center gap-2 transition-all duration-200 ${
                    isCustom ? 'pr-10 group-hover:pr-[68px]' : 'pr-10'
                  } ${
                    isSelected ? 'bg-white/5 text-white' : 'text-zinc-500 hover:text-white hover:bg-white/5'
                  }`}
                >
                  {isSelected && <Icon name="check" size={20} className="opacity-[0.48]" />}
                  <span className="truncate">{style}</span>
                </button>

                {isCustom && (
                  <div className="absolute right-1 top-1/2 -translate-y-1/2 flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-all z-20">
                    {onOpenCustomStyleModal && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onOpenCustomStyleModal(style);
                          setIsMenuOpen(false);
                        }}
                        title="Edit custom style"
                        className="w-7 h-7 flex items-center justify-center rounded-md text-zinc-600 hover:text-white hover:bg-white/10 transition-colors"
                      >
                        <Icon name="edit" size={20} className="opacity-[0.48]" />
                      </button>
                    )}
                    {onRemoveCustomStyle && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onRemoveCustomStyle(style);
                          setIsMenuOpen(false);
                        }}
                        title="Remove custom style"
                        className="w-7 h-7 flex items-center justify-center rounded-md text-zinc-600 hover:text-white hover:bg-white/10 transition-colors"
                      >
                        <Icon name="close" size={20} className="opacity-[0.48]" />
                      </button>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>,
        document.body
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Editor } from '@tiptap/react';
import { Icon } from './Icon';

interface ToolbarProps {
  editor: Editor | null;
}

const IconButton: React.FC<{
  iconName: string;
  onClick: () => void;
  active?: boolean;
  disabled?: boolean;
  title?: string;
}> = ({ iconName, onClick, active, disabled, title }) => (
  <button
    onMouseDown={(e) => {
      // CRITICAL: preventDefault on mousedown stops the editor from losing focus
      e.preventDefault();
      onClick();
    }}
    disabled={disabled}
    title={title}
    className={`p-1.5 rounded-lg transition-all flex items-center justify-center flex-shrink-0 ${
      active 
        ? 'bg-white/10 text-white' 
        : 'text-zinc-500 hover:text-white hover:bg-white/5'
    } disabled:opacity-30 disabled:cursor-not-allowed`}
  >
    <Icon name={iconName} size={18} className={active ? 'text-white' : ''} />
  </button>
);

const TextButton: React.FC<{
  label: string;
  onClick: () => void;
  active?: boolean;
}> = ({ label, onClick, active }) => (
  <button
    onMouseDown={(e) => {
      e.preventDefault();
      onClick();
    }}
    className={`px-3 py-1.5 rounded-lg text-[13px] font-bold transition-all [text-shadow:none] ${
      active 
        ? 'text-white bg-white/10' 
        : 'text-[#DADCE0]/[0.72] hover:text-white hover:bg-white/5'
    }`}
  >
    {label}
  </button>
);

const Toolbar: React.FC<ToolbarProps> = ({ editor }) => {
  const [_, setTick] = useState(0);

  useEffect(() => {
    if (!editor || editor.isDestroyed) return;
    const handler = () => setTick(t => t + 1);
    editor.on('selectionUpdate', handler);
    editor.on('transaction', handler);
    editor.on('update', handler);
    return () => {
      editor.off('selectionUpdate', handler);
      editor.off('transaction', handler);
      editor.off('update', handler);
    };
  }, [editor]);

  if (!editor || editor.isDestroyed) return null;

  // Safety check for view availability
  let isReady = false;
  try {
    isReady = !!(editor.view && editor.view.dom);
  } catch (e) {
    isReady = false;
  }

  const isActive = (name: string, attributes?: any) => {
    if (!isReady) return false;
    try {
      return editor.isActive(name, attributes);
    } catch (e) {
      return false;
    }
  };

  const canUndo = () => {
    if (!isReady) return false;
    try {
      return editor.can().undo();
    } catch (e) {
      return false;
    }
  };

  const canRedo = () => {
    if (!isReady) return false;
    try {
      return editor.can().redo();
    } catch (e) {
      return false;
    }
  };

  return (
    <div className="flex items-center justify-center w-full">
      <div className="flex items-center gap-1">
        {/* Screenplay Block Types — Desktop */}
        <div className="hidden md:flex items-center gap-1 pr-3 border-r border-[#DADCE0]/[0.16]">
          <span className="text-[12px] text-[#DADCE0]/[0.48] font-medium pr-1 select-none">Format:</span>
          <TextButton 
            label="Title" 
            onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()} 
            active={isActive('heading', { level: 1 })}
          />
          <TextButton 
            label="Scene" 
            onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()} 
            active={isActive('heading', { level: 3 })}
          />
          <TextButton 
            label="Dialog" 
            onClick={() => {
              if (!isReady) return;
              // If cursor is on a bold name, select the whole paragraph and remove bold
              if (isActive('bold')) {
                const { $from } = editor.state.selection;
                const parentStart = $from.start($from.depth);
                const parentEnd = $from.end($from.depth);
                editor.chain().focus()
                  .setTextSelection({ from: parentStart, to: parentEnd })
                  .unsetBold()
                  .run();
                return;
              }

              const { from, to } = editor.state.selection;
              const selectedText = editor.state.doc.textBetween(from, to, '\x0a').trim();

              if (selectedText) {
                // Split into first line (name) and rest (dialog)
                const lines = selectedText.split('\x0a');
                const name = lines[0].trim().toUpperCase();
                const dialog = lines.slice(1).join('\x0a').trim();

                const content: any[] = [
                  { type: 'paragraph', content: [{ type: 'text', text: name, marks: [{ type: 'bold' }] }] },
                ];
                if (dialog) {
                  content.push({ type: 'paragraph', content: [{ type: 'text', text: dialog }] });
                } else {
                  content.push({ type: 'paragraph' });
                }

                editor.chain().focus().deleteSelection().insertContent(content).run();
              } else {
                // No selection — insert placeholder
                editor.chain().focus()
                  .insertContent([
                    { type: 'paragraph', content: [{ type: 'text', text: 'NAME', marks: [{ type: 'bold' }] }] },
                    { type: 'paragraph', content: [{ type: 'text', text: 'Dialog goes here...' }] },
                  ])
                  .run();
              }
            }} 
            active={isActive('bold')}
          />
          <TextButton 
            label="Transition" 
            onClick={() => editor.chain().focus().toggleHeading({ level: 5 }).run()} 
            active={isActive('heading', { level: 5 })}
          />
        </div>

        {/* Screenplay Block Types — Mobile Dropdown */}
        <div className="flex md:hidden items-center pr-3 border-r border-[#DADCE0]/[0.16]">
          <select
            value={
              isActive('heading', { level: 1 }) ? 'title'
              : isActive('heading', { level: 3 }) ? 'scene'
              : isActive('bold') ? 'dialog'
              : isActive('heading', { level: 5 }) ? 'transition'
              : ''
            }
            onMouseDown={(e) => e.stopPropagation()}
            onChange={(e) => {
              const val = e.target.value;
              if (val === 'title') {
                editor.chain().focus().toggleHeading({ level: 1 }).run();
              } else if (val === 'scene') {
                editor.chain().focus().toggleHeading({ level: 3 }).run();
              } else if (val === 'dialog') {
                if (!isReady) return;
                const { from, to } = editor.state.selection;
                const selectedText = editor.state.doc.textBetween(from, to, '\x0a').trim();
                if (selectedText) {
                  const lines = selectedText.split('\x0a');
                  const name = lines[0].trim().toUpperCase();
                  const dialog = lines.slice(1).join('\x0a').trim();
                  const content: any[] = [
                    { type: 'paragraph', content: [{ type: 'text', text: name, marks: [{ type: 'bold' }] }] },
                  ];
                  if (dialog) {
                    content.push({ type: 'paragraph', content: [{ type: 'text', text: dialog }] });
                  } else {
                    content.push({ type: 'paragraph' });
                  }
                  editor.chain().focus().deleteSelection().insertContent(content).run();
                } else {
                  editor.chain().focus()
                    .insertContent([
                      { type: 'paragraph', content: [{ type: 'text', text: 'NAME', marks: [{ type: 'bold' }] }] },
                      { type: 'paragraph', content: [{ type: 'text', text: 'Dialog goes here...' }] },
                    ])
                    .run();
                }
              } else if (val === 'transition') {
                editor.chain().focus().toggleHeading({ level: 5 }).run();
              }
              // Reset so re-selecting the same value fires onChange again
              e.target.value = '';
              editor.commands.focus();
            }}
            className="bg-transparent border border-[#DADCE0]/[0.24] rounded-lg py-1.5 px-2 pr-7 text-[13px] font-bold text-[#DADCE0]/[0.72] focus:outline-none appearance-none cursor-pointer font-sans"
          >
            <option value="" disabled className="bg-zinc-900">Format</option>
            <option value="title" className="bg-zinc-900">Title</option>
            <option value="scene" className="bg-zinc-900">Scene</option>
            <option value="dialog" className="bg-zinc-900">Dialog</option>
            <option value="transition" className="bg-zinc-900">Transition</option>
          </select>
        </div>

        {/* Formatting Icons */}
        <div className="flex items-center gap-1 px-3 border-r border-[#DADCE0]/[0.16]">
          <IconButton 
            iconName="format_italic" 
            onClick={() => editor.chain().focus().toggleItalic().run()} 
            active={isActive('italic')} 
            title="Italic" 
          />
          <IconButton 
            iconName="format_underlined" 
            onClick={() => editor.chain().focus().toggleUnderline().run()} 
            active={isActive('underline')} 
            title="Underline" 
          />
          <IconButton 
            iconName="format_list_bulleted" 
            onClick={() => editor.chain().focus().toggleBulletList().run()} 
            active={isActive('bulletList')} 
            title="Bullet List" 
          />
          <IconButton 
            iconName="mode_comment" 
            onClick={() => editor.chain().focus().toggleBlockquote().run()} 
            active={isActive('blockquote')}
            title="Add Feedback Comment" 
          />
        </div>

        {/* History Icons */}
        <div className="flex items-center gap-1 pl-3">
          <IconButton 
            iconName="undo" 
            onClick={() => editor.chain().focus().undo().run()} 
            disabled={!canUndo()} 
            title="Undo" 
          />
          <IconButton 
            iconName="redo" 
            onClick={() => editor.chain().focus().redo().run()} 
            disabled={!canRedo()} 
            title="Redo" 
          />
        </div>
      </div>
    </div>
  );
};

export default Toolbar;

import React, { useState, useRef, useCallback } from 'react';

interface TooltipProps {
  text: string;
  children: React.ReactNode;
  position?: 'top' | 'bottom';
}

export const Tooltip: React.FC<TooltipProps> = ({ text, children, position = 'top' }) => {
  const [visible, setVisible] = useState(false);
  const [coords, setCoords] = useState({ x: 0, y: 0 });
  const timeoutRef = useRef<number>();
  const triggerRef = useRef<HTMLDivElement>(null);

  const show = useCallback(() => {
    timeoutRef.current = window.setTimeout(() => {
      if (triggerRef.current) {
        const rect = triggerRef.current.getBoundingClientRect();
        setCoords({
          x: rect.left + rect.width / 2,
          y: position === 'top' ? rect.top - 8 : rect.bottom + 8,
        });
      }
      setVisible(true);
    }, 400);
  }, [position]);

  const hide = useCallback(() => {
    clearTimeout(timeoutRef.current);
    setVisible(false);
  }, []);

  return (
    <div ref={triggerRef} className="relative inline-flex" onMouseEnter={show} onMouseLeave={hide}>
      {children}
      {visible && (
        <div
          className="fixed z-[9999] pointer-events-none whitespace-nowrap px-2.5 py-1 rounded-md bg-[#1a1a1a] border border-white/10 text-[11px] font-medium text-white/80 shadow-xl"
          style={{
            left: coords.x,
            top: coords.y,
            transform: position === 'top' ? 'translate(-50%, -100%)' : 'translate(-50%, 0)',
          }}
        >
          {text}
        </div>
      )}
    </div>
  );
};

