/**
 * Global Rolling Queue for Flow API image generation.
 *
 * Enforces a strict global concurrency limit without using complex
 * semaphore locking. When multiple views or actions trigger autofill
 * concurrently, their items are pushed to this global queue and
 * processed 2 at a time globally.
 */

class GlobalRollingQueue {
  private queue: {
    task: () => Promise<void>;
    signal: AbortSignal;
    resolve: () => void;
    reject: (e: any) => void;
  }[] = [];
  private activeWorkers = 0;
  private concurrency = 2;
  private readonly SLOT_COOLDOWN_MS = 200;

  async enqueue(task: () => Promise<void>, signal: AbortSignal): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      this.queue.push({ task, signal, resolve, reject });
      this.processNext();
    });
  }

  private async processNext() {
    if (this.activeWorkers >= this.concurrency || this.queue.length === 0) return;

    // Flush any aborted tasks immediately
    while (this.queue.length > 0 && this.queue[0].signal.aborted) {
      const skipped = this.queue.shift()!;
      skipped.resolve();
    }

    if (this.queue.length === 0) return;

    this.activeWorkers++;
    const current = this.queue.shift()!;

    try {
      if (!current.signal.aborted) {
        await current.task();
      }
      current.resolve();
    } catch (e) {
      current.reject(e);
    } finally {
      this.activeWorkers--;
      // Small cooldown to spread API pressure
      setTimeout(() => this.processNext(), this.SLOT_COOLDOWN_MS);
    }
  }
}

const globalImagePool = new GlobalRollingQueue();

/**
 * Wait for ALL currently in-flight slots to finish.
 * (Deprecated: kept as no-op for backward compatibility)
 */
export function waitForDrain(): Promise<void> {
  return Promise.resolve();
}

/**
 * Run an async function gated by the global semaphore.
 * (Deprecated: kept for backward compatibility, now just runs the function)
 */
export async function withSlot<T>(fn: () => Promise<T>): Promise<T> {
  return await fn();
}

/**
 * Rolling concurrency pool — maintains a global active worker limit.
 * All items passed here are pushed to the global queue, ensuring
 * that even concurrent calls to `runRollingQueue` don't exceed the global limit.
 *
 * @param items - Array of items to process
 * @param worker - Async function to process each item. Receives the item AND the abort signal.
 * @param concurrency - Max simultaneous workers (ignored in favor of global concurrency=2)
 * @param signal - AbortSignal to cancel pending items AND passed into each worker
 * @param onProgress - Called after each item completes with (completed, failed) counts
 */
export async function runRollingQueue<T>(
  items: T[],
  worker: (item: T, signal: AbortSignal) => Promise<void>,
  concurrency: number,
  signal: AbortSignal,
  onProgress: (completed: number, failed: number) => void,
  manageSlots: boolean = true
): Promise<{ completed: number; failed: number }> {
  let completed = 0;
  let failed = 0;

  const promises = items.map(async (item) => {
    if (signal.aborted) return;
    try {
      await globalImagePool.enqueue(async () => {
        if (signal.aborted) return;
        await worker(item, signal);
      }, signal);

      if (signal.aborted) return;
      completed++;
      onProgress(completed, failed);
    } catch (err) {
      if (signal.aborted) return;
      console.error('Queue item failed:', err);
      failed++;
      onProgress(completed, failed);
    }
  });

  await Promise.all(promises);
  return { completed, failed };
}

/**
 * Retry an async function with exponential backoff.
 * Waits 2s, then 4s (with random jitter) between attempts.
 * Respects an optional AbortSignal to bail early.
 *
 * IMPORTANT: Timeout errors (180s) and rate-limit errors (429) are NOT retried
 * because they indicate server-side conditions that won't resolve in seconds.
 * Only transient errors (network blips, 500s) are retried.
 */
export async function withRetry<T>(
  fn: () => Promise<T>,
  maxRetries: number = 2,
  signal?: AbortSignal
): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    if (signal?.aborted) throw new Error('Aborted');
    try {
      return await fn();
    } catch (err: any) {
      lastError = err;
      // Don't retry if aborted
      if (signal?.aborted) throw err;

      // Don't retry non-transient errors — these won't resolve with a quick retry
      const msg = (err?.message || '').toLowerCase();
      const isTimeout = msg.includes('timed out') || msg.includes('timeout');
      const isRateLimit = msg.includes('429') || msg.includes('rate limit') || msg.includes('quota');
      const isContentFilter = msg.includes('blocked') || msg.includes('safety') || msg.includes('filtered');
      if (isTimeout || isRateLimit || isContentFilter) {
        throw err; // Fail fast — don't waste another 180s
      }

      if (attempt < maxRetries) {
        // Exponential backoff: 2s, 4s (with jitter to spread out retries)
        const baseDelay = 2000 * Math.pow(2, attempt);
        const jitter = Math.random() * 1000;
        await new Promise(r => setTimeout(r, baseDelay + jitter));
      }
    }
  }
  throw lastError;
}

import { ScriptScene, SCENE_HEADING_REGEX, SCENE_ID_REGEX } from '../types';

export const TRANSITION_REGEX = /^(FADE IN|FADE OUT|FADE TO|CUT TO|DISSOLVE TO|SMASH CUT TO|MATCH CUT TO|JUMP CUT TO|WIPE TO|IRIS IN|IRIS OUT)[\s:.\-]*$/i;

export const generateId = () => `scene-${Math.random().toString(36).substr(2, 9)}`;

export const parseScriptToScenes = (markdown: string): ScriptScene[] => {
  if (!markdown) return [];

  // Aggressively normalize to single and double newlines only, and unescape markdown characters
  const normalizedMarkdown = markdown
    .replace(/\\([#*_\-\.>`])/g, '$1') // Unescape characters escaped by Turndown
    .replace(/\x0d\x0a/g, '\x0a')
    .replace(/\x0a{3,}/g, '\x0a\x0a');

  const rawLines = normalizedMarkdown.split('\x0a');
  const lines: string[] = [];

  // Pre-process lines to collapse empty lines after characters and parentheticals
  for (let i = 0; i < rawLines.length; i++) {
    const line = rawLines[i];
    const prevLine = i > 0 ? rawLines[i - 1].trim() : '';
    const nextLine = i < rawLines.length - 1 ? rawLines[i + 1].trim() : '';

    if (line.trim() === '') {
      const isPrevTransition = TRANSITION_REGEX.test(prevLine.replace(/^#+\s*/, ''));
      const isPrevHeading = SCENE_HEADING_REGEX.test(prevLine);
      const isPrevAllCaps = !isPrevTransition && !isPrevHeading && /^[A-Z0-9\s.()'"\-]+$/.test(prevLine) && prevLine.length > 1 && prevLine.length < 45;
      const isPrevParenthetical = /^\(.+?\)$/.test(prevLine) || /^\*\(.+?\)\*$/.test(prevLine) || /^_.*_$/.test(prevLine);

      if ((isPrevAllCaps || isPrevParenthetical) && nextLine !== '') {
        continue; // Skip this empty line to snap dialogue to the character name
      }
    }
    lines.push(line);
  }

  const scenes: ScriptScene[] = [];

  let currentContent: string[] = [];
  let currentHeading = 'PREAMBLE';
  let currentId = 'scene-preamble';
  let sceneIndex = 0;

  const pushScene = () => {
    const content = currentContent.join('\x0a').trim();
    if (content || currentHeading !== 'PREAMBLE') {
      const idMatch = content.match(SCENE_ID_REGEX);
      const finalId = idMatch ? idMatch[1] : currentId;

      const baseContent = content.replace(SCENE_ID_REGEX, '').trim();
      const finalContent = `<!-- scene-id: ${finalId} -->\x0a${baseContent}`;

      scenes.push({
        id: finalId,
        heading: currentHeading,
        content: finalContent,
        order: sceneIndex++,
        isPreamble: currentHeading === 'PREAMBLE'
      });
    }
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === undefined || line === null) continue;

    const isHeading = SCENE_HEADING_REGEX.test(line);
    const isTransition = TRANSITION_REGEX.test(line.replace(/^#+\s*/, ''));

    if (isHeading && !isTransition) {
      pushScene();
      currentId = generateId();
      const rawHeading = line.replace(/^(#{1,3}\s*)?/, '').trim().toUpperCase();
      currentHeading = rawHeading;
      currentContent = [`### ${rawHeading}`];
    } else if (isTransition) {
      const rawTransition = line.replace(/^(#{1,5}\s*)?/, '').replace(/[\s:.\-]*$/, '').trim().toUpperCase();
      currentContent.push(`##### ${rawTransition}:`);
    } else {
      if (!SCENE_ID_REGEX.test(line)) {
        const trimmed = line.trim();
        const nextLine = lines[i + 1]?.trim();

        const isAllCaps = /^[A-Z0-9\s.()'"\-]+$/.test(trimmed) && trimmed.length > 1 && trimmed.length < 45;
        const isParenthetical = /^\(.+?\)$/.test(trimmed);

        if (isAllCaps && !trimmed.startsWith('**') && nextLine && nextLine !== '') {
          currentContent.push(`**${trimmed}**`);
        } else if (isParenthetical && !trimmed.startsWith('_') && !trimmed.startsWith('*')) {
          currentContent.push(`_(${trimmed.slice(1, -1)})_`);
        } else {
          currentContent.push(line);
        }
      }
    }
  }

  pushScene();
  return scenes;
};

export const validateAndCleanScenes = (scenes: ScriptScene[]): ScriptScene[] => {
  const seenIds = new Set<string>();
  return scenes.map(scene => {
    let id = scene.id;
    if (seenIds.has(id) || !id) {
      id = generateId();
    }
    seenIds.add(id);

    let content = scene.content.replace(/<!--\s*scene-id:\s*([a-zA-Z0-9-]+)\s*-->/g, '').trim();
    // Ensure internal scene whitespace is cleaned up
    content = content.replace(/\x0a{3,}/g, '\x0a\x0a');
    content = `<!-- scene-id: ${id} -->\x0a${content}`;

    return { ...scene, id, content };
  });
};

export const joinScenes = (scenes: ScriptScene[]): string => {
  return scenes
    .sort((a, b) => (a.order || 0) - (b.order || 0))
    .map(s => s.content.trim())
    .join('\x0a\x0a');
};

import { ScriptScene } from '../types';

const SCENE_HEADING_PATTERN = /^(#{1,3}\s*)?(EXT\.|INT\.|EXT\/INT\.|I\/E\.)/i;
const TRANSITION_REGEX = /^(FADE IN|FADE OUT|FADE TO|CUT TO|DISSOLVE TO|SMASH CUT TO|MATCH CUT TO|JUMP CUT TO|WIPE TO|IRIS IN|IRIS OUT)[\s:.\-]*$/i;
const SCENE_ID_COMMENT_PATTERN = /^<!--\s*scene-id:\s*([a-zA-Z0-9-]+)\s*-->/;

export const parseScript = (text: string): ScriptScene[] => {
  const lines = text.split('\x0a');
  const scenes: ScriptScene[] = [];

  let currentScene: Partial<ScriptScene> = {
    id: 'scene-preamble',
    slugline: 'PREAMBLE',
    content: '',
    isPreamble: true
  };

  let nextSceneId: string | null = null;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // Check for ID comment
    const idMatch = line.match(SCENE_ID_COMMENT_PATTERN);
    if (idMatch) {
      nextSceneId = idMatch[1];
      continue;
    }

    // Check for scene heading
    const isHeading = SCENE_HEADING_PATTERN.test(line);
    const isTransition = TRANSITION_REGEX.test(line);

    if (isHeading && !isTransition) {
      // Save previous scene
      if (currentScene.content?.trim() || currentScene.id !== 'scene-preamble') {
        scenes.push(currentScene as ScriptScene);
      }

      // Start new scene
      currentScene = {
        id: nextSceneId || crypto.randomUUID(),
        slugline: line.replace(/^#{1,3}\s*/, '').toUpperCase(),
        content: '',
        isPreamble: false
      };
      nextSceneId = null;
    } else {
      currentScene.content += (currentScene.content ? '\x0a' : '') + lines[i];
    }
  }

  // Push final scene
  if (currentScene.content?.trim() || !currentScene.isPreamble) {
    scenes.push(currentScene as ScriptScene);
  }

  return scenes;
};

/**
 * Sanitizes script text for AI consumption.
 * Now strips double newlines and extra spaces to maximize context density.
 */
export const sanitizeForAI = (text: string): string => {
  return text
    .split('\x0a')
    .filter(line => {
      const l = line.trim();
      if (!l) return false; // Strip empty lines to save characters
      // Allow scene headings (### INT. ...) but strip main title (# ...)
      if (l.startsWith('# ') || l.startsWith('## ')) return false; 
      if (l.startsWith('>')) return false; 
      if (l.startsWith('<!--')) return false; 
      return true;
    })
    .map(line => line.trim()) // Strip indentation
    .join('\x0a');
};

import TurndownService from 'turndown';

const turndownService = new TurndownService({
  headingStyle: 'atx',
  codeBlockStyle: 'fenced'
});

// CRITICAL: Disable escaping so scene-id comments and markdown symbols stay intact
turndownService.escape = (text) => text;

// Preserve existing scene comments if they are already in the DOM
turndownService.addRule('sceneComments', {
  filter: (node) => node.nodeType === 8, // Comment node
  replacement: (content) => `<!--${content}-->`
});

// Convert data-scene-id attributes back to markdown comments
turndownService.addRule('preserveSceneIds', {
  filter: (node) => node.nodeName === 'H3' && node.hasAttribute('data-scene-id'),
  replacement: (content, node) => {
    const element = node as HTMLElement;
    const sceneId = element.getAttribute('data-scene-id');
    return `\x0a<!-- scene-id: ${sceneId} -->\x0a### ${content}\x0a`;
  }
});

// Convert <br> back to newlines properly
turndownService.addRule('lineBreaks', {
  filter: 'br',
  replacement: () => '\x0a'
});

export { turndownService };

export const toTitleCase = (str: string): string => {
  if (!str) return '';
  return str
    .toLowerCase()
    .split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
};

import { Asset, CharacterAsset, LocationAsset, PropAsset } from '../types';

/**
 * An asset is "empty" if it has no user/AI-generated content:
 * - No autofilled descriptions (physicalCharacteristics, clothing, backstory, timeOfDay)
 * - No generated or imported images
 * - No user-written description
 * - No inspiration image
 */
export function isAssetEmpty(asset: Asset): boolean {
  const hasNoImages = asset.supportingImages.length === 0;
  const hasNoInspiration = !asset.inspirationImage;
  const hasNoDescription = !asset.description;

  const hasNoTypeFields = (() => {
    if (asset.type === 'character') {
      const a = asset as CharacterAsset;
      return !a.physicalCharacteristics && !a.clothingAccessories && !a.backstory;
    }
    if (asset.type === 'location') {
      const a = asset as LocationAsset;
      return !a.physicalCharacteristics && !a.timeOfDay;
    }
    return !(asset as PropAsset).physicalCharacteristics;
  })();

  return hasNoImages && hasNoTypeFields && hasNoDescription && hasNoInspiration;
}

/**
 * Find assets whose names no longer appear anywhere in the script text.
 * Uses conservative case-insensitive substring matching to avoid false positives.
 */
export function findOrphanedAssets(assets: Asset[], script: string): Asset[] {
  const lowerScript = script.toLowerCase();
  return assets.filter(asset => !lowerScript.includes(asset.name.toLowerCase()));
}

